class Resource {};

// Acquire resource (RAII guaranteed)
std::unique_ptr<Resource> ptr = std::make_unique<Resource>();

// Access resource
ptr->method();
Resource& ref = *ptr;

// Exclusive ownership enforced: copy forbidden
// std::unique_ptr<Resource> p_fail = ptr; // Error

// Ownership transfer requires explicit move
std::unique_ptr<Resource> p_moved = std::move(ptr);

// Get raw pointer (Use only for interaction with C APIs)
Resource* raw = p_moved.get();

// Release resource immediately (calls destructor)
p_moved.reset();

// Resource automatically deleted when p_moved goes out of scope.
